const diagnosis = JSON.parse($json.diagnosis_json);

return [{
  json: {
    incident_id: $json.id,
    workflow_id: $json.workflow_id,
    workflow_file: `workflows/${$json.workflow_id}.json`,
    diagnosis: {
      root_cause: diagnosis.root_cause,
      proposed_fix: diagnosis.proposed_fix,
      files_to_change: diagnosis.files_to_change
    }
  }
}];

const raw = $json.stdout;
const lines = raw.trim().split('\n').reverse();
const jsonLine = lines.find(l => l.trim().startsWith('{'));
const envelope = JSON.parse(jsonLine);

let resultText = envelope.result.trim();
const fenceMatch = resultText.match(/```json\s*([\s\S]*?)```/i);
if (fenceMatch) {
  resultText = fenceMatch[1].trim();
}

let fixResult;
try {
  fixResult = JSON.parse(resultText);
} catch (e) {
  // Claude didn't return clean JSON (e.g. a tool call got blocked and it
  // explained in prose instead) — don't let this die silently. Surface the
  // raw explanation so the human still gets notified with something
  // actionable, instead of the whole execution erroring out with no message.
  fixResult = {
    status: 'needs_manual_review',
    branch: null,
    pr_url: null,
    commit: null,
    abort_reason: resultText
  };
}

return [{
  json: {
    status: fixResult.status,
    branch: fixResult.branch,
    pr_url: fixResult.pr_url,
    commit: fixResult.commit,
    abort_reason: fixResult.abort_reason,
    cost_usd: envelope.total_cost_usd
  }
}];

